    "Website SEO data (free: Open PageRank)": "بيانات SEO للموقع (مجاني: Open PageRank)",
    "Free: get a key at openpagerank.keywordseverywhere.com/dashboard (sign in with a Keywords Everywhere key; old DomCop keys no longer work). It gives a 0-10 authority score and the world rank of a lead website. Used when no Ahrefs or Ubersuggest key answers. The basic SEO checks (title, description, mobile, indexing, robots.txt, sitemap) need no key at all.": "مجاني: احصل على مفتاح من openpagerank.keywordseverywhere.com/dashboard (يكفي حساب). يعطي درجة سلطة من 0 إلى 10 والترتيب العالمي لموقع العميل المحتمل. يُستخدم عندما لا يستجيب مفتاح Ahrefs أو Ubersuggest. الفحوص الأساسية (العنوان، الوصف، الجوال، الفهرسة، robots.txt، خريطة الموقع) لا تحتاج أي مفتاح.",
    "Open PageRank API key": "مفتاح Open PageRank API",
    "World rank": "الترتيب العالمي",
    "SEO basics": "أساسيات SEO",
    "SEO figures (authority, traffic, keywords, backlinks) appear here once an Ahrefs, Ubersuggest or free Open PageRank key is saved in Settings → AI.": "تظهر أرقام SEO (السلطة، الزيارات، الكلمات المفتاحية، الروابط الخلفية) هنا بعد حفظ مفتاح Ahrefs أو Ubersuggest أو Open PageRank (مجاني) في الإعدادات ← الذكاء الاصطناعي.",
    "Website SEO data (Ahrefs)": "بيانات SEO للموقع (Ahrefs)",
    "With your Ahrefs API key (API v3), hovering the website of a lead shows its domain rating, organic traffic and keywords, and backlinks. When both keys are saved, Ahrefs is used. The key is stored encrypted and never shown again.": "بمفتاح Ahrefs API (الإصدار 3)، يعرض المرور فوق موقع العميل المحتمل تصنيف النطاق والزيارات والكلمات المفتاحية العضوية والروابط الخلفية. إذا وُجد المفتاحان يُستخدم Ahrefs. يُخزَّن المفتاح مشفراً ولا يُعرض مرة أخرى.",
    "Ahrefs API key": "مفتاح Ahrefs API",
    "SEO figures (authority, traffic, keywords, backlinks) appear here once an Ahrefs or Ubersuggest key is saved in Settings → AI.": "تظهر أرقام SEO (السلطة، الزيارات، الكلمات المفتاحية، الروابط الخلفية) هنا بعد حفظ مفتاح Ahrefs أو Ubersuggest في الإعدادات ← الذكاء الاصطناعي.",
