    "All languages": "كل اللغات",
    "This client has no contact with an email address. Add one in Other recipients.": "ليس لهذا العميل أي جهة اتصال لها بريد إلكتروني. أضف واحدة في مستلمون آخرون.",
    "from": "من",
    "Show the signature on invoices (until paid)": "إظهار التوقيع على الفواتير (حتى تُدفع)",
    "Prints the signature from General → Document logos. An invoice stops printing it once it is paid.": "يطبع التوقيع من عام ← شعارات المستندات. تتوقف الفاتورة عن طباعته بعد دفعها.",
    "Prints the signature from General → Document logos. On: it prints once an invoice is paid or a contract is signed, never before. Off: it prints on no PDF.": "يطبع التوقيع من عام ← شعارات المستندات. عند التشغيل: يُطبع على كل فاتورة وعقد، مدفوعًا أو لا. عند الإيقاف: لا يُطبع على أي ملف PDF.",
    "The invoice, its lines, its activity and its payments will be removed. This can upset your accounts and reports.": "ستُحذف الفاتورة وبنودها ونشاطها ومدفوعاتها. قد يؤثر ذلك على حساباتك وتقاريرك.",
    "Pick a date and a time": "اختر تاريخًا ووقتًا",
    "Bank account assigned": "تم تعيين الحساب البنكي",
    "Number - month - year: PREFIX 0012 - 12 - 26": "الرقم - الشهر - السنة: البادئة 0012 - 12 - 26",
    "Add your WhatsApp number in the Profile tab first.": "أضف رقم واتساب أولًا في تبويب الملف الشخصي.",
    "Save the settings above first: the test uses the saved accounts.": "احفظ الإعدادات أعلاه أولًا: يستخدم الاختبار الحسابات المحفوظة.",
    "Send /start to the company bot, then enter your chat id (for example from @userinfobot).": "أرسل /start إلى بوت الشركة ثم أدخل معرّف الدردشة (مثلًا من @userinfobot).",
    "Send a test": "إرسال اختبار",
    "Telegram": "تيليغرام",
    "Telegram chat id": "معرّف دردشة تيليغرام",
    "Test message sent": "تم إرسال رسالة الاختبار",
    "The same notifications as by email, as a short message with the link. Your administrator sets up the accounts in Settings.": "الإشعارات نفسها كما بالبريد، برسالة قصيرة مع الرابط. يقوم المسؤول بإعداد الحسابات في الإعدادات.",
    "WhatsApp and Telegram": "واتساب وتيليغرام",
    "WhatsApp number": "رقم واتساب",
    "WhatsApp & Telegram": "واتساب وتيليغرام",
    "Send notifications by WhatsApp and Telegram, next to email": "إرسال الإشعارات عبر واتساب وتيليغرام إلى جانب البريد",
    "Create a bot with @BotFather and paste its token. Each person then sends /start to the bot and enters their chat id (for example from @userinfobot) in their profile.": "أنشئ بوتًا عبر @BotFather والصق رمزه. ثم يرسل كل شخص /start إلى البوت ويُدخل معرّف دردشته (مثلًا من @userinfobot) في ملفه الشخصي.",
    "Send notifications by Telegram": "إرسال الإشعارات عبر تيليغرام",
    "Bot token": "رمز البوت",
    "WhatsApp (Cloud API)": "واتساب (Cloud API)",
    "From Meta for Developers → WhatsApp → API setup: the phone number ID and a permanent access token. Outside a 24 hour conversation WhatsApp only delivers approved templates: give the name of a template with one body variable and its language, or leave it empty for plain messages.": "من Meta for Developers ← واتساب ← إعداد API: معرّف رقم الهاتف ورمز وصول دائم. خارج نافذة المحادثة لمدة 24 ساعة يسلّم واتساب القوالب المعتمدة فقط: أدخل اسم قالب بمتغير نصي واحد ولغته، أو اتركه فارغًا للرسائل العادية.",
    "Send notifications by WhatsApp": "إرسال الإشعارات عبر واتساب",
    "Phone number ID": "معرّف رقم الهاتف",
    "Access token": "رمز الوصول",
    "Template name (optional)": "اسم القالب (اختياري)",
    "Template language": "لغة القالب",
    "For example en, fr, es, ja, ar.": "مثل en أو fr أو es أو ja أو ar.",
    "Notify by WhatsApp": "الإشعار عبر واتساب",
    "Notify by Telegram": "الإشعار عبر تيليغرام",
    "Drag to a column to make it a task": "اسحبها إلى عمود لتحويلها إلى مهمة",
    "Give the note a title": "أعطِ الملاحظة عنوانًا",
    "How do you want to be notified?": "كيف تريد أن تتلقى الإشعارات؟",
    "Make it a task": "تحويلها إلى مهمة",
    "New note": "ملاحظة جديدة",
    "Note deleted": "تم حذف الملاحظة",
    "Note saved": "تم حفظ الملاحظة",
    "Pick one or several: the same notification arrives on each channel you switch on. Your administrator sets up Telegram and WhatsApp in Settings.": "اختر قناة أو أكثر: يصل الإشعار نفسه عبر كل قناة تُفعّلها. يقوم المسؤول بإعداد تيليغرام وواتساب في الإعدادات.",
    "The note is now a task": "أصبحت الملاحظة مهمة",
    "Apply the numbering to all invoices?": "هل تريد تطبيق الترقيم على جميع الفواتير؟",
    "Apply to all existing invoices": "تطبيق على جميع الفواتير الحالية",
    "Every invoice gets the saved prefix and number format. Only how the number reads changes, never the number.": "تحصل كل فاتورة على البادئة والتنسيق المحفوظين. يتغير شكل عرض الرقم فقط، ولا يتغير الرقم نفسه.",
    "{n} invoices now read {prefix}…": "أصبحت {n} فاتورة تظهر بصيغة {prefix}…",
    "Existing invoices": "الفواتير الحالية",
    "Save the numbering above first. Then give every invoice the same prefix and number format, so they all read alike (for example FA - 101 - 10 - 2026). The numbers themselves do not change.": "احفظ الترقيم أعلاه أولاً. ثم امنح كل فاتورة البادئة والتنسيق نفسيهما لتظهر جميعها بالشكل نفسه (مثال: FA - 101 - 10 - 2026). الأرقام نفسها لا تتغير.",
    "Quick notes: a title and a description": "ملاحظات سريعة: عنوان ووصف",
    "No notes yet. Use New note to add one.": "لا توجد ملاحظات بعد. استخدم «ملاحظة جديدة» لإضافة واحدة.",
