    "Expected": "المتوقع",
    "Hours are the time the CRM is open and in use (a click, key press or scroll in the last two minutes). Nothing outside the CRM is measured. The working week is set in Settings → Localization → Working hours.": "الساعات هي المدة التي يكون فيها النظام مفتوحًا ومستخدمًا (نقرة أو ضغطة مفتاح أو تمرير في آخر دقيقتين). لا يُقاس أي شيء خارج النظام. يُحدَّد أسبوع العمل في الإعدادات ← التوطين ← ساعات العمل.",
