    "Working hours": "ساعات العمل",
    "The working week the Work hours page measures against: hours per day, without the break. The time is the company clock above.": "أسبوع العمل الذي تقارن به صفحة ساعات العمل: ساعات كل يوم بدون الاستراحة. الوقت هو توقيت الشركة أعلاه.",
    "Day starts at": "بداية اليوم",
    "HH:MM, for example 09:00. Opening the CRM after this time plus the grace below counts as late.": "HH:MM مثل 09:00. فتح النظام بعد هذا الوقت مع مهلة السماح أدناه يُعدّ تأخرًا.",
    "Grace before late (minutes)": "مهلة قبل التأخر (دقائق)",
