    "Your administrator requires two-step sign-in. Turn on the authenticator app or the email code below to keep using the CRM.": "يشترط المسؤول تسجيل الدخول بخطوتين. فعّل تطبيق المصادقة أو رمز البريد أدناه لمتابعة استخدام النظام.",
    "Your administrator requires two-step sign-in: turn it on in your profile, Security, to continue.": "يشترط المسؤول تسجيل الدخول بخطوتين: فعّله من ملفك الشخصي، الأمان، للمتابعة.",
