    "Make the second step (authenticator app or email code) compulsory. Someone the rule covers who has not turned it on can only open their profile, Security, until they do. Everybody can always turn it on themselves.": "اجعل الخطوة الثانية (تطبيق المصادقة أو رمز البريد) إلزامية. من تشمله القاعدة ولم يفعّلها لا يستطيع فتح غير ملفه الشخصي، الأمان، حتى يفعل. يمكن للجميع تفعيلها بأنفسهم.",
    "Backups": "النسخ الاحتياطية",
