    "Back up the database every night": "نسخ قاعدة البيانات احتياطياً كل ليلة",
    "Every night after 02:00 (company time) the whole database is saved to the file storage: the last 14 days and one a week for 12 weeks. It does not need the automatic tasks to be on.": "كل ليلة بعد 02:00 (توقيت الشركة) تُحفظ قاعدة البيانات كاملة في تخزين الملفات: آخر 14 يوماً ونسخة أسبوعياً لمدة 12 أسبوعاً. لا يتطلب تشغيل المهام التلقائية.",
    "Alerts": "التنبيهات",
    "Send alerts to the administrators": "إرسال التنبيهات إلى المسؤولين",
    "The administrators are told (bell, email, Telegram / WhatsApp) when a backup fails or is late, when the automatic tasks stop or report errors, and when the CRM returns a burst of server errors. The same alert is sent once an hour at most.": "يُنبَّه المسؤولون (الجرس والبريد وتيليجرام / واتساب) عند فشل نسخة احتياطية أو تأخرها، أو توقف المهام التلقائية أو إبلاغها عن أخطاء، أو عند سيل من أخطاء الخادم. يُرسل التنبيه نفسه مرة واحدة في الساعة كحد أقصى.",
