    "Let another app of yours (the Meet app) sign the team in with their CRM account. Only active team members can sign in: clients never. Guests of a meeting use the meeting link and are admitted by a team member.": "اسمح لتطبيق آخر لديك (Meet) بتسجيل دخول الفريق بحساب CRM. يدخل أعضاء الفريق النشطون فقط، ولا يدخل العملاء أبدًا. يستخدم ضيوف الاجتماع رابط الاجتماع ويقبلهم أحد أعضاء الفريق.",
