    "Delete this message?": "حذف هذه الرسالة؟",
    "Done or switched off": "منتهية أو متوقفة",
    "Edit the message": "تعديل الرسالة",
    "First time, at": "أول مرة، في",
    "Good morning team, the weekly meeting is at 10:00 on meet.trtcrm.com/internal": "صباح الخير فريقنا، الاجتماع الأسبوعي الساعة 10:00 على meet.trtcrm.com/internal",
    "It goes out at the first run of the automatic tasks after that time (Settings → Cron job), so they must run often, for example every 5 minutes.": "تُرسل عند أول تشغيل للمهام التلقائية بعد ذلك الوقت (الإعدادات ← Cron job)، لذا يجب أن تعمل كثيرًا، مثلًا كل 5 دقائق.",
    "Message deleted": "تم حذف الرسالة",
    "Message saved": "تم حفظ الرسالة",
    "Messages the CRM posts in the team chat by itself at the date and time you choose, once or repeating: announcements, rules, reminders, the weekly meeting. They appear as sent by you.": "رسائل ينشرها CRM بنفسه في دردشة الفريق في التاريخ والوقت اللذين تختارهما، مرة واحدة أو بتكرار: إعلانات وقواعد وتذكيرات والاجتماع الأسبوعي. تظهر كأنك أرسلتها.",
