    "2 = today and tomorrow cannot be booked (nobody books the day before). 1 = from tomorrow. 0 = no limit.": "2 = لا يمكن الحجز اليوم ولا غداً (لا أحد يحجز في اليوم السابق). 1 = ابتداءً من الغد. 0 = بلا حد.",
