    "Say what you sell. The AI proposes items with a description, a unit and a price; you choose the ones to add.": "اكتب ما تبيعه. يقترح الذكاء الاصطناعي عناصر بوصف ووحدة وسعر، وتختار ما تريد إضافته.",
